INSERT INTO `hero_slides` VALUES (1,1,'Breaking New Grounds in Sustainability','Forging a Path Towards a Brighter Tomorrow','Refex promotes sustainability through innovative solutions, products, and services that create environmental, social, and financial value in a world where sustainability is the need of the hour for businesses',8136,'Know More','/about-refex','MCl9yK2HWo8',0,1,'2025-12-15 12:58:04','2025-12-27 07:17:05'),(2,1,'Reliable and Sustainable Refrigerant solutions.','REFRIGERANTS','A market leader in refrigerant gas manufacturing, we are also conscious innovators. Discover our eco-friendly alternatives to make the step towards a greener tomorrow.',7947,'Know More','/refex-refrigerants',NULL,1,1,'2025-12-15 12:58:04','2025-12-24 07:32:10'),(3,1,'Powering the Future with Green Energy','REFEX Renewables','Building a safe and healthy future with limitless clean and green energy by inculcating innovative methods to have a sustainable future.',7948,'Know More','/refex-renewables',NULL,2,1,'2025-12-15 12:58:04','2025-12-24 07:37:39'),(4,1,'Reliable and responsible coal handling solutions.','REFEX Coal & Ash handling','Experience unprecedented efficiency and reliability in coal and ash handling by elevating it with Refex.',7950,'Know More','/refex-ash-coal-handling',NULL,3,1,'2025-12-15 12:58:04','2025-12-24 07:47:32'),(5,1,'Engineering Innovation for Good Health','REFEX MedTech','Creating extraordinary diagnostic tools and providing expert technical guidance to make healthcare affordable and accessible to all.',7951,'Know More','/refex-medtech',NULL,4,1,'2025-12-15 12:58:04','2025-12-24 07:48:27'),(6,1,'Fuelling great ideas into new possibilities','REFEX Capital','We focus on investing in disruptive start-ups with the aim of advancing technology and defining the future.',7952,'Know More','/refex-capital',NULL,5,1,'2025-12-15 12:58:04','2025-12-24 07:49:11');
