INSERT INTO `newsroom_items` VALUES (1,'press','Dinesh Agarwal, CEO of Refex Group, on ET Now',NULL,'Dinesh Agarwal, CEO of Refex Group, on ET Now','/uploads/images/general/general/general-general-et-now-logo-svg-1024x819-1766566915270-682381.png',1,'https://www.youtube.com/watch?v=vyiEp-hzhqU','PRESS RELEASE',7982,'ET NOW',1,1,'2025-12-15 13:18:30','2025-12-24 09:16:57','2025-11-11 00:00:00'),(3,'press','Refex Mobility expands operations to Delhi NCR',NULL,'Refex Mobility expands operations to Delhi NCR','/uploads/images/general/general/general-general-et-autor-1766571323298-220488.svg',2,'https://auto.economictimes.indiatimes.com/news/aftermarket/refex-eveelz-rebrands-as-refex-mobility-to-consolidate-focus-on-existing-tier-1-market/123237339','PRESS RELEASE',7984,'ET AUTO',1,1,'2025-12-15 13:18:30','2025-12-24 10:15:28','2025-11-11 00:00:00'),(13,'event','Refex Gheun Tak – A Women\'s Ultimate Frisbee Tournament','Times of India',NULL,NULL,16,'https://businessnewsthisweek.com/business/team-meraki-wins-refex-gheun-tak-a-womens-ultimate-frisbee-tournament/','Event',7998,'Event',1,1,'2025-12-15 13:18:30','2025-12-30 05:57:31','2023-01-25 00:00:00'),(14,'event','Refex Group Road Safety Awareness event','Events',NULL,NULL,15,'https://navjeevanexpress.com/csr-initiative-refex-group-kick-starts-road-safety-campaign-on-anna-salai-in-chennai/',' Event',7997,'Event',1,1,'2025-12-15 13:18:30','2025-12-30 05:58:03','2023-01-11 00:00:00'),(15,'press','Refex eVeelz rebrands as Refex Mobility; to consolidate focus on existing Tier-1 market','Refex eVeelz rebrands to Refex Mobility with focus on Tier-1 markets',NULL,'/uploads/images/general/general/general-general-et-autor-1766571370444-466269.svg',3,'https://auto.economictimes.indiatimes.com/news/aftermarket/refex-eveelz-rebrands-as-refex-mobility-to-consolidate-focus-on-existing-tier-1-market/123237339','PRESS RELEASE',7985,'press',0,1,'2025-12-19 12:37:50','2025-12-24 10:16:12','2024-09-20 00:00:00'),(16,'press','Refex Group is the Official Sponsor of Chennai Super Kings','Refex Group announces official sponsorship of Chennai Super Kings',NULL,'/uploads/images/general/general/general-general-logo-white-1766571504323-23182.png',5,'https://www.aninews.in/news/business/refex-group-is-the-official-sponsor-of-chennai-super-kings20250327190124/','PRESS RELEASE',7987,'press',0,1,'2025-12-19 12:37:50','2025-12-24 10:18:26','2024-07-20 00:00:00'),(17,'press','Uber partners with Chennai-based Refex Green Mobility to deploy 1,000 EVs across cities','Uber partners with Refex Green Mobility to deploy 1,000 electric vehicles',NULL,'/uploads/images/general/general/general-general-thehindu-logo-1766571568373-544676.svg',6,'https://www.thehindu.com/sci-tech/technology/uber-partners-with-chennai-based-refex-green-mobility-to-deploy-1000-evs-across-cities/article69316319.ece','PRESS RELEASE',7988,'press',0,1,'2025-12-19 12:37:50','2025-12-24 10:19:30','2024-06-10 00:00:00'),(18,'press','Refex Group Strengthens Leadership in Sustainability at UNGCNI Annual Convention 2025','Refex Group showcases sustainability leadership at UNGCNI Annual Convention',NULL,'/uploads/images/general/general/general-general-logo-white-1766571527374-432051.png',7,'https://www.aninews.in/news/business/refex-group-strengthens-leadership-in-sustainability-at-ungcni-annual-convention-202520250215101613/','PRESS RELEASE',7989,'press',0,1,'2025-12-19 12:37:50','2025-12-24 10:18:49','2025-02-15 00:00:00'),(19,'press','Refex reports PBT at 30 crore in Q1 FY24','Refex Industries reports Profit Before Tax of 30 crore in Q1 FY24',NULL,'/uploads/images/general/general/general-general-the-times-of-india-logo-1-1024x539-1766571714638-697297.png',8,'https://timesofindia.indiatimes.com/city/chennai/refex-reports-pbt-at-30-crore-in-q1-fy24/articleshow/102408182.cms?from=mdr','PRESS RELEASE',7990,'press',0,1,'2025-12-19 12:37:50','2025-12-24 10:22:16','2024-05-15 00:00:00'),(20,'press','Refex Industries\' share price hits upper circuit on good FY23